

create proc [dbo].[StoresBalance]
@variable BIGINT,
@CostCenter NVARCHAR(100),
@id_ven BIGINT
as
if @variable =0
 
     BEGIN
				select'⁄›Ê« ·« Ì„ﬂ‰ «·»ÕÀ ⁄‰ «·’›— '   
				RETURN '0'
     END
ELSE   
     BEGIN
DECLARE @VisbleThreeUnit BIT=1 
SELECT @VisbleThreeUnit= VisbleThreeUnit FROM ZZproperties

IF @VisbleThreeUnit=1
 BEGIN
       IF @CostCenter='' and @id_ven=0 SELECT   SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 8)) AS BalanceInStore,ROUND(SUM(Convert(float,Profit )), 3) AS Profit ,  convert(nvarchar,ROUND(SUM(Convert(float,comee - outt)), 3)) AS BalanceStore ,null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,LTRIM(RTRIM(STR(ISNULL(CurrentBalance0, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance1, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance2, 0)))) AS balance, id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0,ROUND(CONVERT(FLOAT,BigPr1),2) AS BigPr1,ROUND(CONVERT(FLOAT,BigPr2),2) AS BigPr2,Discount0,Discount1,Discount2, ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1,   TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store, CountMiddel, CountSmall, ROUND(SUM(Convert(float,comee)), 3) AS come_, ROUND(SUM(Convert(float,outt)), 3)  AS out_, Dioscount_main, Minimum, ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal , TYPE FROM   View_store WHERE     (id_store = @variable)  GROUP BY id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, BigPr0,BigPr1,BigPr2,Discount0,Discount1,Discount2, cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store,  CountMiddel, CountSmall, CurrentBalance0, CurrentBalance1, CurrentBalance2, Dioscount_main, Minimum, TYPE, net_balance HAVING       (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )
       IF @CostCenter='' and @id_ven>0 SELECT   null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,convert(nvarchar,SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 8))) AS  BalanceInStore,ROUND(SUM(Convert(float,Profit )), 3) AS Profit ,LTRIM(RTRIM(Convert(NVARCHAR(50),SUM(Convert(float,comee - outt))))) AS BalanceStore,  id_item, InternationalCode,keep,LTRIM(RTRIM(STR(ISNULL(CurrentBalance0, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance1, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance2, 0)))) AS balance,ShortName, CountMetr,ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0,ROUND(CONVERT(FLOAT,BigPr1),2) AS BigPr1,ROUND(CONVERT(FLOAT,BigPr2),2) AS BigPr2,Discount0,Discount1,Discount2,ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1, TypeItem2, TypeItem3,TypeItem4,TypeItem5,TypeItem6,TypeItem7, id_store, CountMiddel, CountSmall, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, SUM(comee) AS comee,SUM(outt) AS outt, LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, comee))))) + ' ' + LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, (comee - CONVERT(Bigint, comee)) * CountMiddel + .001))))) + ' ' + LTRIM(RTRIM(STR(SUM(ROUND((comee - (CONVERT(Bigint, comee) + CONVERT(Bigint, (comee - CONVERT(Bigint, comee)) * CountMiddel) / CountMiddel)) * CountSmall, 0))))) AS come_, LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, outt)))))  + ' ' + LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, (outt - CONVERT(Bigint, outt)) * CountMiddel + .001))))) + ' ' + LTRIM(RTRIM(STR(SUM(ROUND((outt - (CONVERT(Bigint, outt)  + CONVERT(Bigint, (outt - CONVERT(Bigint, outt)) * CountMiddel) / CountMiddel)) * CountSmall + .01, 0))))) AS out_, ROUND(Convert(FLOAT,Dioscount_main),2) AS Dioscount_main, Minimum, ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal ,TYPE FROM  View_store WHERE     (id_store = @variable) and id_ven =@id_ven GROUP BY id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, BigPr0,BigPr1,BigPr2,Discount0,Discount1,Discount2, net_balance, cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3,TypeItem4,TypeItem5,TypeItem6,TypeItem7, id_store, CountMiddel, CountSmall, CurrentBalance0,  CurrentBalance1, CurrentBalance2, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))),  Dioscount_main, Minimum,TYPE HAVING  (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )
       IF @CostCenter<>'' and @id_ven>0 SELECT null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,convert(nvarchar,SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 8))) AS BalanceInStore, ROUND(SUM(Convert(float,Profit )), 3) AS Profit ,LTRIM(RTRIM(Convert(NVARCHAR(50),SUM(Convert(float,comee - outt))))) AS BalanceStore,  id_item, InternationalCode,keep,LTRIM(RTRIM(STR(ISNULL(CurrentBalance0, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance1, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance2, 0)))) AS balance, ShortName, CountMetr,ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0,ROUND(CONVERT(FLOAT,BigPr1),2) AS BigPr1,ROUND(CONVERT(FLOAT,BigPr2),2) AS BigPr2,Discount0,Discount1,Discount2, ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1, TypeItem2, TypeItem3,TypeItem4,TypeItem5,TypeItem6,TypeItem7, id_store, CountMiddel, CountSmall, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, SUM(comee) AS comee,SUM(outt) AS outt, LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, comee))))) + ' ' + LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, (comee - CONVERT(Bigint, comee)) * CountMiddel + .001))))) + ' ' + LTRIM(RTRIM(STR(SUM(ROUND((comee - (CONVERT(Bigint, comee) + CONVERT(Bigint, (comee - CONVERT(Bigint, comee)) * CountMiddel) / CountMiddel)) * CountSmall, 0))))) AS come_, LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, outt))))) + ' ' + LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, (outt - CONVERT(Bigint, outt)) * CountMiddel + .001))))) + ' ' + LTRIM(RTRIM(STR(SUM(ROUND((outt - (CONVERT(Bigint, outt) + CONVERT(Bigint, (outt - CONVERT(Bigint, outt)) * CountMiddel) / CountMiddel)) * CountSmall + .01, 0))))) AS out_, ROUND(Convert(FLOAT,Dioscount_main),2) AS Dioscount_main, Minimum, ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal ,TYPE FROM  View_store WHERE     (id_store = @variable) AND (CostCenter = @CostCenter) and id_ven =@id_ven GROUP BY id_item, InternationalCode,keep, net_balance, ShortName,CountMetr, ARname, ENname, BigPr0,BigPr1,BigPr2,Discount0,Discount1,Discount2, cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3,TypeItem4,TypeItem5,TypeItem6,TypeItem7, id_store, CountMiddel, CountSmall, CurrentBalance0, CurrentBalance1, CurrentBalance2, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))), Dioscount_main, Minimum,TYPE HAVING  (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )       
       IF @CostCenter='' and @id_ven=0 SELECT  null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,convert(nvarchar,SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 8))) AS BalanceInStore,ROUND(SUM(Convert(float,Profit )), 3) AS Profit , LTRIM(RTRIM(Convert(NVARCHAR(50),SUM(Convert(float,comee - outt))))) AS BalanceStore,  id_item, InternationalCode,keep,LTRIM(RTRIM(STR(ISNULL(CurrentBalance0, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance1, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance2, 0)))) AS balance,ShortName,CountMetr, ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0,ROUND(CONVERT(FLOAT,BigPr1),2) AS BigPr1,ROUND(CONVERT(FLOAT,BigPr2),2) AS BigPr2,Discount0,Discount1,Discount2,ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1, TypeItem2, TypeItem3,TypeItem4,TypeItem5,TypeItem6,TypeItem7, id_store, CountMiddel, CountSmall, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, SUM(comee) AS comee,SUM(outt) AS outt, LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, comee))))) + ' ' + LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, (comee - CONVERT(Bigint, comee)) * CountMiddel + .001))))) + ' ' + LTRIM(RTRIM(STR(SUM(ROUND((comee - (CONVERT(Bigint, comee) + CONVERT(Bigint, (comee - CONVERT(Bigint, comee)) * CountMiddel) / CountMiddel)) * CountSmall, 0))))) AS come_, LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, outt)))))  + ' ' + LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, (outt - CONVERT(Bigint, outt)) * CountMiddel + .001))))) + ' ' + LTRIM(RTRIM(STR(SUM(ROUND((outt - (CONVERT(Bigint, outt)  + CONVERT(Bigint, (outt - CONVERT(Bigint, outt)) * CountMiddel) / CountMiddel)) * CountSmall + .01, 0))))) AS out_, ROUND(Convert(FLOAT,Dioscount_main),2) AS Dioscount_main, Minimum, ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal ,TYPE FROM  View_store WHERE     (id_store = @variable) GROUP BY id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, BigPr0,BigPr1,BigPr2,Discount0,Discount1,Discount2, net_balance, cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3,TypeItem4,TypeItem5,TypeItem6,TypeItem7, id_store, CountMiddel, CountSmall, CurrentBalance0,  CurrentBalance1, CurrentBalance2, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))),  Dioscount_main, Minimum,TYPE HAVING  (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )
       IF @CostCenter<>'' and @id_ven=0 SELECT null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,convert(nvarchar,SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 8))) AS BalanceInStore, ROUND(SUM(Convert(float,Profit )), 3) AS Profit ,LTRIM(RTRIM(Convert(NVARCHAR(50),SUM(Convert(float,comee - outt))))) AS BalanceStore,  id_item, InternationalCode,keep,LTRIM(RTRIM(STR(ISNULL(CurrentBalance0, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance1, 0)))) + ' ' + LTRIM(RTRIM(STR(ISNULL(CurrentBalance2, 0)))) AS balance, ShortName,CountMetr, ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0,ROUND(CONVERT(FLOAT,BigPr1),2) AS BigPr1,ROUND(CONVERT(FLOAT,BigPr2),2) AS BigPr2,Discount0,Discount1,Discount2, ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1, TypeItem2, TypeItem3,TypeItem4,TypeItem5,TypeItem6,TypeItem7, id_store, CountMiddel, CountSmall, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, SUM(comee) AS comee,SUM(outt) AS outt, LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, comee))))) + ' ' + LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, (comee - CONVERT(Bigint, comee)) * CountMiddel + .001))))) + ' ' + LTRIM(RTRIM(STR(SUM(ROUND((comee - (CONVERT(Bigint, comee) + CONVERT(Bigint, (comee - CONVERT(Bigint, comee)) * CountMiddel) / CountMiddel)) * CountSmall, 0))))) AS come_, LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, outt))))) + ' ' + LTRIM(RTRIM(STR(SUM(CONVERT(Bigint, (outt - CONVERT(Bigint, outt)) * CountMiddel + .001))))) + ' ' + LTRIM(RTRIM(STR(SUM(ROUND((outt - (CONVERT(Bigint, outt) + CONVERT(Bigint, (outt - CONVERT(Bigint, outt)) * CountMiddel) / CountMiddel)) * CountSmall + .01, 0))))) AS out_, ROUND(Convert(FLOAT,Dioscount_main),2) AS Dioscount_main, Minimum, ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal ,TYPE FROM  View_store WHERE     (id_store = @variable) AND (CostCenter = @CostCenter) GROUP BY id_item, InternationalCode,keep, net_balance, ShortName,CountMetr, ARname, ENname, BigPr0,BigPr1,BigPr2,Discount0,Discount1,Discount2, cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3,TypeItem4,TypeItem5,TypeItem6,TypeItem7, id_store, CountMiddel, CountSmall, CurrentBalance0, CurrentBalance1, CurrentBalance2, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))), Dioscount_main, Minimum,TYPE HAVING  (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )
  END
ELSE
  BEGIN
          IF @CostCenter='' and @id_ven>0 SELECT    SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 8)) AS BalanceInStore,ROUND(SUM(Convert(float,Profit )), 3) AS Profit , ROUND(SUM(Convert(float,comee - outt)), 3) AS BalanceStore ,null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,ROUND(Convert(float,net_balance),3) AS balance, id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0,ROUND(CONVERT(FLOAT,BigPr1),2) AS BigPr1,ROUND(CONVERT(FLOAT,BigPr2),2) AS BigPr2,Discount0,Discount1,Discount2, ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1,   TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store, CountMiddel, CountSmall, ROUND(SUM(Convert(float,comee)), 3) AS come_, ROUND(SUM(Convert(float,outt)), 3)  AS out_, Dioscount_main, Minimum, ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal , TYPE FROM   View_store WHERE     (id_store = @variable) and id_ven =@id_ven GROUP BY id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, BigPr0,BigPr1,BigPr2,Discount0,Discount1,Discount2, cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store,  CountMiddel, CountSmall, CurrentBalance0, CurrentBalance1, CurrentBalance2, Dioscount_main, Minimum, TYPE, net_balance HAVING       (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )
          IF @CostCenter<>'' and @id_ven>0 SELECT   SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 8)) AS BalanceInStore,ROUND(SUM(Convert(float,Profit )), 3) AS Profit ,  ROUND(SUM(Convert(float,comee - outt)), 3) AS BalanceStore,null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,ROUND(Convert(float,net_balance),3) AS balance,ROUND(Convert(float,net_balance),3) AS net_balance, id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0,ROUND(CONVERT(FLOAT,BigPr1),2) AS BigPr1,ROUND(CONVERT(FLOAT,BigPr2),2) AS BigPr2,Discount0,Discount1,Discount2, ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1,   TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store, CountMiddel, CountSmall, ROUND(SUM(Convert(float,comee)), 3) AS come_, ROUND(SUM(Convert(float,outt)), 3)  AS out_, Dioscount_main, Minimum,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal , TYPE FROM   View_store WHERE     (id_store = @variable)AND (CostCenter = @CostCenter) and id_ven =@id_ven GROUP BY id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, BigPr0,BigPr1,BigPr2,Discount0,Discount1,Discount2, cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store,  CountMiddel, CountSmall, CurrentBalance0, CurrentBalance1, CurrentBalance2, Dioscount_main, Minimum, TYPE, net_balance HAVING       (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )      
          IF @CostCenter<>'' and @id_ven=0 SELECT   SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 8)) AS BalanceInStore, ROUND(SUM(Convert(float,Profit )), 3) AS Profit , ROUND(SUM(Convert(float,comee - outt)), 3) AS BalanceStore,null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,ROUND(Convert(float,net_balance),3) AS balance, id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0,ROUND(CONVERT(FLOAT,BigPr1),2) AS BigPr1,ROUND(CONVERT(FLOAT,BigPr2),2) AS BigPr2,Discount0,Discount1,Discount2, ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1,   TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store, CountMiddel, CountSmall, ROUND(SUM(Convert(float,comee)), 3) AS come_, ROUND(SUM(Convert(float,outt)), 3)  AS out_, Dioscount_main, Minimum,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal , TYPE FROM   View_store WHERE     (id_store = @variable)AND (CostCenter = @CostCenter) GROUP BY id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, BigPr0,BigPr1,BigPr2, Discount0,Discount1,Discount2,cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store,  CountMiddel, CountSmall, CurrentBalance0, CurrentBalance1, CurrentBalance2, Dioscount_main, Minimum, TYPE, net_balance HAVING       (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )
          IF @CostCenter='' and @id_ven=0 SELECT   SUM(ROUND(CONVERT(float,(isnull(comee,0) - isnull(outt,0))) , 2)) AS BalanceInStore,ROUND(SUM(Convert(float,Profit )), 3) AS Profit ,  ROUND(SUM(Convert(float,comee - outt)), 3) AS BalanceStore ,null as InventoryBalance,null as InventoryBalance1,null as InventoryBalance2,ROUND(Convert(float,net_balance),3) AS balance, id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, ROUND(CONVERT(FLOAT,BigPr0),2) AS BigPr0, ROUND(CONVERT(FLOAT,cost),2) AS cost,ROUND(CONVERT(FLOAT,PurchasePrice),2) AS PurchasePrice,ROUND(CONVERT(FLOAT,Dioscount_over),3) as Dioscount_over, TypeItem1,   TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store, CountMiddel, CountSmall, ROUND(SUM(Convert(float,comee)), 3) AS come_, ROUND(SUM(Convert(float,outt)), 3)  AS out_, Dioscount_main, Minimum, ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * cost), 2)), 2) AS total_cost,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * PurchasePrice * (100 - Dioscount_main) / 100), 2)), 2) AS total_pur ,ROUND(SUM(ROUND(CONVERT(float, ((comee - outt)) * BigPr0 ), 2)), 2) AS total_StoreSal , TYPE FROM   View_store WHERE     (id_store = @variable)  GROUP BY id_item, InternationalCode,keep, ShortName,CountMetr, ARname, ENname, BigPr0, cost,PurchasePrice,Dioscount_over, TypeItem1, TypeItem2, TypeItem3, TypeItem4, TypeItem5, TypeItem6, TypeItem7, id_store,  CountMiddel, CountSmall, CurrentBalance0, CurrentBalance1, CurrentBalance2, Dioscount_main, Minimum, TYPE, net_balance HAVING      (ISNULL(TYPE, 0) <> 2 and ISNULL(TYPE, 0) <> 4 )
